//! Build script for `tpm2-boringssl`.
//!
//! Requires a BoringSSL source tree (`BORINGSSL_SOURCE_DIR`) and a CMake build
//! directory configured with `-DRUST_BINDINGS=<target>` (`BORINGSSL_BUILD_DIR`).
//! See the crate's `README.md` for details.
//!
//! This script:
//! 1. Copies the `bssl-sys` bindings generated by BoringSSL's CMake build
//!    (`rust/bssl-sys/wrapper_<target>.rs`) into `OUT_DIR`, where they are
//!    `include!`d by the crate's private `bssl_sys` module.
//! 2. Copies `libcrypto.a` into `OUT_DIR` under a unique name and links it
//!    statically (plus the C++ runtime). The build directory itself is never
//!    added as a link search path, so binaries which also link OpenSSL's
//!    `libcrypto` / `libssl` (e.g. via `openssl-sys`) still resolve those to
//!    OpenSSL.
//! 3. Runs `bindgen` on BoringSSL's internal `bcm_interface.h` (and
//!    `curve25519/internal.h`) for entry points `bssl-sys` doesn't export.

use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

/// Name of the copied BoringSSL `libcrypto.a` (as `lib<name>.a`) in `OUT_DIR`.
const CRYPTO_LIB_NAME: &str = "tpm2_bssl_crypto";

/// Returns the directory in the (required) environment variable `name`.
fn required_dir(name: &str, help: &str) -> PathBuf {
    println!("cargo:rerun-if-env-changed={name}");
    let Some(val) = env::var_os(name).filter(|v| !v.is_empty()) else {
        panic!(
            "\n\n`{name}` is not set. tpm2-boringssl requires `{name}` to be set to {help}. \
             See crates/tpm2-boringssl/README.md.\n\n"
        );
    };
    let dir = PathBuf::from(val);
    assert!(
        dir.is_dir(),
        "\n\n`{name}` ({}) is not a directory. It must be set to {help}. \
         See crates/tpm2-boringssl/README.md.\n\n",
        dir.display()
    );
    dir
}

/// Returns the `bindgen` executable: `$BINDGEN` if set, otherwise `bindgen`
/// (looked up on `PATH`).
fn find_bindgen() -> PathBuf {
    println!("cargo:rerun-if-env-changed=BINDGEN");
    env::var_os("BINDGEN")
        .filter(|v| !v.is_empty())
        .map_or_else(|| PathBuf::from("bindgen"), PathBuf::from)
}

/// Returns the C++ runtime library BoringSSL's `libcrypto` needs (overridable
/// via `BORINGSSL_RUST_CPPLIB`, matching `bssl-sys`).
fn cpp_runtime_lib() -> Option<String> {
    println!("cargo:rerun-if-env-changed=BORINGSSL_RUST_CPPLIB");
    if let Ok(cpp_lib) = env::var("BORINGSSL_RUST_CPPLIB") {
        return (!cpp_lib.is_empty()).then_some(cpp_lib);
    }
    if env::var_os("CARGO_CFG_UNIX").is_some() {
        match env::var("CARGO_CFG_TARGET_OS").as_deref() {
            Ok("macos" | "ios") => Some("c++".into()),
            _ => Some("stdc++".into()),
        }
    } else {
        None
    }
}

fn copy_file(from: &Path, to: &Path, help: &str) {
    println!("cargo:rerun-if-changed={}", from.display());
    fs::copy(from, to).unwrap_or_else(|e| {
        panic!(
            "\n\nfailed to copy {} to {}: {e}\n{help}\n\n",
            from.display(),
            to.display()
        )
    });
}

fn detect_boringssl_prefix(build_dir: &Path) -> Option<String> {
    let cache_path = build_dir.join("CMakeCache.txt");
    println!("cargo:rerun-if-changed={}", cache_path.display());
    let contents = fs::read_to_string(cache_path).ok()?;
    for line in contents.lines() {
        if let Some(rest) = line.strip_prefix("BORINGSSL_PREFIX:")
            && let Some((_, val)) = rest.split_once('=')
        {
            let trimmed = val.trim();
            if !trimmed.is_empty() {
                return Some(trimmed.to_owned());
            }
        }
    }
    None
}

fn strip_prefix_from_bindings(path: &Path, prefix: &str) {
    let needle = format!("bssl_{prefix}_");
    let contents = fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    let replaced = contents.replace(&needle, "bssl_");
    fs::write(path, replaced).unwrap_or_else(|e| panic!("failed to write {}: {e}", path.display()));
}

fn run_bindgen(bindgen: &Path, header: &Path, allowlist: &[&str], out: &Path, clang: &[String]) {
    let status = Command::new(bindgen)
        .arg(header)
        .arg("--use-core")
        .args(allowlist)
        .arg("-o")
        .arg(out)
        .arg("--")
        .args(clang)
        .status()
        .unwrap_or_else(|e| {
            panic!(
                "\n\nfailed to execute `{}`: {e}\nInstall bindgen (`cargo install bindgen-cli`) \
                 and put it on PATH, or set BINDGEN to its path.\n\n",
                bindgen.display()
            )
        });
    assert!(
        status.success(),
        "bindgen failed on {} with status {status}",
        header.display()
    );
}

fn main() {
    let bssl_src = required_dir(
        "BORINGSSL_SOURCE_DIR",
        "the BoringSSL source tree (containing `include/` and `crypto/`)",
    );
    let bssl_build_dir = required_dir(
        "BORINGSSL_BUILD_DIR",
        "a BoringSSL CMake build directory configured with `-DRUST_BINDINGS=<target>`",
    );
    let target = env::var("TARGET").expect("TARGET must be set");
    let out_dir = PathBuf::from(env::var_os("OUT_DIR").expect("OUT_DIR must be set"));

    // 1. `bssl-sys` bindings generated by BoringSSL's CMake build.
    let wrapper = bssl_build_dir.join(format!("rust/bssl-sys/wrapper_{target}.rs"));
    copy_file(
        &wrapper,
        &out_dir.join("bssl_sys_bindings.rs"),
        &format!(
            "BORINGSSL_BUILD_DIR must be configured with `-DRUST_BINDINGS={target}` and built \
             (`ninja -C <build-dir>`)."
        ),
    );

    // 2. Statically link a uniquely named copy of `libcrypto.a`.
    copy_file(
        &bssl_build_dir.join("libcrypto.a"),
        &out_dir.join(format!("lib{CRYPTO_LIB_NAME}.a")),
        "BORINGSSL_BUILD_DIR must contain a built `libcrypto.a` (`ninja -C <build-dir>`).",
    );
    println!("cargo:rustc-link-search=native={}", out_dir.display());
    println!("cargo:rustc-link-lib=static={CRYPTO_LIB_NAME}");
    if let Some(cpp_lib) = cpp_runtime_lib() {
        println!("cargo:rustc-link-lib={cpp_lib}");
    }

    // 3. `bindgen` bindings for BoringSSL internal headers.
    let prefix = detect_boringssl_prefix(&bssl_build_dir);

    let bcm_header = bssl_src.join("crypto/fipsmodule/bcm_interface.h");
    let c25519_header = bssl_src.join("crypto/curve25519/internal.h");
    let include_dir = bssl_src.join("include");
    println!("cargo:rerun-if-changed={}", bcm_header.display());
    println!("cargo:rerun-if-changed={}", c25519_header.display());

    let out_file = out_dir.join("bcm_bindings.rs");
    let c25519_out_file = out_dir.join("curve25519_bindings.rs");

    let mut clang_args = vec![
        "-x".to_owned(),
        "c++".to_owned(),
        "-std=c++17".to_owned(),
        format!("-I{}", include_dir.display()),
        format!("-I{}", bssl_build_dir.join("include").display()),
    ];
    if let Some(p) = &prefix {
        clang_args.push(format!("-DBORINGSSL_PREFIX={p}"));
    }

    let bindgen = find_bindgen();
    run_bindgen(
        &bindgen,
        &bcm_header,
        &[
            "--allowlist-function=bssl::(.*::)?BCM_.*",
            "--allowlist-type=bssl::(.*::)?bcm_.*",
        ],
        &out_file,
        &clang_args,
    );
    run_bindgen(
        &bindgen,
        &c25519_header,
        &["--allowlist-function=bssl::(.*::)?x25519_.*"],
        &c25519_out_file,
        &clang_args,
    );

    if let Some(p) = &prefix {
        strip_prefix_from_bindings(&out_file, p);
        strip_prefix_from_bindings(&c25519_out_file, p);
    }
}
